<?php require_once 'includes/functions.php';$slug=$_GET['slug']??'';$st=$pdo->prepare("SELECT p.*,c.name category_name FROM places p LEFT JOIN categories c ON c.id=p.category_id WHERE p.slug=? AND p.status='published'");$st->execute([$slug]);$place=$st->fetch();if(!$place){http_response_code(404);exit('Destination not found');}$page_title=$place['name'];$rv=$pdo->prepare("SELECT r.*,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.place_id=? AND r.status='approved' ORDER BY r.created_at DESC");$rv->execute([$place['id']]);$reviews=$rv->fetchAll();$saved=false;if(logged_in()){$f=$pdo->prepare('SELECT id FROM favorites WHERE user_id=? AND place_id=?');$f->execute([user()['id'],$place['id']]);$saved=(bool)$f->fetch();}$photos=array_filter([$place['cover_image'],$place['gallery_1'],$place['gallery_2'],$place['gallery_3']]);require 'includes/header.php';?>
<section class="detail-hero" style="background-image:linear-gradient(0deg,rgba(0,0,0,.78),rgba(0,0,0,.04)),url('<?=e(image_url($place['cover_image']))?>')"><div><span class="chip chip-blue"><?=e($place['category_name'])?></span><h1><?=e($place['name'])?></h1><p>⌖ <?=e($place['district'])?>, Bangladesh　 ★ <?=number_format((float)$place['rating'],1)?> (<?=count($reviews)?> reviews)</p></div></section><section class="detail-layout"><div><nav class="tabs"><a href="#overview">Overview</a><a href="#how">How to Go</a><a href="#stay">Where to Stay</a><a href="#things">Things to Do</a><a href="#reviews">Reviews</a></nav><article class="content-block" id="overview"><h2>About <?=e($place['name'])?></h2><p><?=nl2br(e($place['description']))?></p><div class="info-list"><div><b>⌖ Location</b><span><?=e($place['district'])?></span></div><div><b>▣ Category</b><span><?=e($place['category_name'])?></span></div><div><b>◷ Best Time</b><span><?=e($place['best_time']?:'October – March')?></span></div><div><b>৳ Estimated Budget</b><span><?=money($place['estimated_budget'])?> – <?=money($place['estimated_budget']*1.8)?></span></div></div></article><article class="content-block" id="how"><h2>How to Go</h2><p><?=nl2br(e($place['how_to_go']?:'Choose a bus, train or flight to the nearest transport hub, then take local transport to the destination.'))?></p></article><article class="content-block" id="stay"><h2>Where to Stay</h2><p><?=nl2br(e($place['where_to_stay']?:'Hotels, guest houses and local accommodation options are available nearby.'))?></p></article><article class="content-block" id="things"><h2>Things to Do</h2><p><?=nl2br(e($place['things_to_do']?:'Enjoy sightseeing, local food, photography and the natural surroundings.'))?></p></article><article class="content-block" id="reviews"><h2>Reviews & Ratings</h2><?php if(logged_in()):?><form method="post" action="user/review.php" class="review-form"><?=csrf_field()?><input type="hidden" name="place_id" value="<?=$place['id']?>"><select name="rating" required><option value="5">★★★★★ - Excellent</option><option value="4">★★★★ - Very good</option><option value="3">★★★ - Good</option><option value="2">★★ - Fair</option><option value="1">★ - Poor</option></select><textarea name="comment" required placeholder="Share your experience..."></textarea><button class="btn btn-primary">Submit review</button></form><?php else:?><p><a href="<?=url('auth/login.php')?>">Login</a> to write a review.</p><?php endif;?><?php foreach($reviews as $r):?><div class="review"><b><?=e($r['name'])?> <span class="rating-text">★ <?=$r['rating']?>/5</span></b><p><?=e($r['comment'])?></p></div><?php endforeach;?></article></div><aside class="detail-aside"><div class="gallery"><img src="<?=e(image_url($place['cover_image']))?>" alt=""><div><?php foreach(array_slice(array_values($photos),1,3) as $ph):?><img src="<?=e(image_url($ph))?>" alt=""><?php endforeach;?></div></div><div class="quick-card"><h3>Quick Info</h3><p><b>How to Go</b><span>Bus / Train / Flight</span></p><p><b>Where to Stay</b><span>Hotels / Resorts / Guest House</span></p><p><b>Things to Do</b><span><?=e($place['things_to_do']?:'Sightseeing, food, photography')?></span></p></div><?php if(logged_in()):?><form method="post" action="user/favorite.php"><?=csrf_field()?><input type="hidden" name="place_id" value="<?=$place['id']?>"><button class="btn btn-primary btn-block" name="action" value="toggle"><?=$saved?'♥ Saved to Favorites':'♡ Add to Favorites'?></button></form><a class="btn btn-outline btn-block" href="<?=url('user/trips.php?add='.$place['id'])?>">＋ Add to My Trip</a><?php else:?><a class="btn btn-primary btn-block" href="<?=url('auth/login.php')?>">Login to save this place</a><?php endif;?></div></aside></section><?php require 'includes/footer.php';?>
